-- A despejar estrutura para tabela aquapoint.aqua_points
CREATE TABLE IF NOT EXISTS `aqua_points` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `point_name` text NOT NULL,
  `point_type` int(11) NOT NULL,
  `point_trust` int(11) NOT NULL DEFAULT 2,
  `local_id` int(11) NOT NULL,
  `state_id` int(11) DEFAULT 3,
  `image` longblob DEFAULT NULL,
  `latitude` double NOT NULL,
  `longitude` double NOT NULL,
  `createdAt` datetime DEFAULT current_timestamp(),
  `createdBy` int(11) DEFAULT NULL,
  `isPending` tinyint(4) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_aqua_points_type` (`point_type`),
  KEY `fk_aqua_points_local` (`local_id`),
  KEY `FK_aqua_points_trustlevels` (`point_trust`),
  KEY `FK_aqua_points_states` (`state_id`),
  KEY `fk_aqua_points_created_by` (`createdBy`),
  CONSTRAINT `FK_aqua_points_states` FOREIGN KEY (`state_id`) REFERENCES `states` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_aqua_points_trustlevels` FOREIGN KEY (`point_trust`) REFERENCES `trustlevels` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_aqua_points_created_by` FOREIGN KEY (`createdBy`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_aqua_points_local` FOREIGN KEY (`local_id`) REFERENCES `local` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_aqua_points_type` FOREIGN KEY (`point_type`) REFERENCES `type` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

